class Solution {
  public List<Integer> spiralOrder(int[][] matrix) {
    List<Integer> answer = new ArrayList<>();
    int top = 0, bottom = matrix.length - 1;
    int left = 0, right = matrix[0].length - 1;

    while (top <= bottom && left <= right) {
      for (int c = left; c <= right; c++) answer.add(matrix[top][c]);
      top++;
      for (int r = top; r <= bottom; r++) answer.add(matrix[r][right]);
      right--;
      if (top <= bottom) {
        for (int c = right; c >= left; c--) answer.add(matrix[bottom][c]);
        bottom--;
      }
      if (left <= right) {
        for (int r = bottom; r >= top; r--) answer.add(matrix[r][left]);
        left++;
      }
    }
    return answer;
  }
}

class Solution {
  public int[][] generateMatrix(int n) {
    int[][] matrix = new int[n][n];
    int top = 0, bottom = n - 1;
    int left = 0, right = n - 1;
    int value = 1;

    while (top <= bottom && left <= right) {
      for (int c = left; c <= right; c++) matrix[top][c] = value++;
      top++;
      for (int r = top; r <= bottom; r++) matrix[r][right] = value++;
      right--;
      for (int c = right; c >= left && top <= bottom; c--) matrix[bottom][c] = value++;
      bottom--;
      for (int r = bottom; r >= top && left <= right; r--) matrix[r][left] = value++;
      left++;
    }
    return matrix;
  }
}

class Solution {
  public void rotate(int[][] matrix) {
    int n = matrix.length;
    for (int r = 0; r < n; r++) {
      for (int c = r + 1; c < n; c++) {
        int temp = matrix[r][c];
        matrix[r][c] = matrix[c][r];
        matrix[c][r] = temp;
      }
    }

    for (int r = 0; r < n; r++) {
      int left = 0, right = n - 1;
      while (left < right) {
        int temp = matrix[r][left];
        matrix[r][left++] = matrix[r][right];
        matrix[r][right--] = temp;
      }
    }
  }
}

class Solution {
  public boolean searchMatrix(int[][] matrix, int target) {
    int m = matrix.length;
    int n = matrix[0].length;
    int left = 0;
    int right = m * n - 1;

    while (left <= right) {
      int mid = left + (right - left) / 2;
      int value = matrix[mid / n][mid % n];
      if (value == target) return true;
      if (value < target) left = mid + 1;
      else right = mid - 1;
    }
    return false;
  }
}

class Solution {
  public boolean searchMatrix(int[][] matrix, int target) {
    int r = 0;
    int c = matrix[0].length - 1;
    while (r < matrix.length && c >= 0) {
      int value = matrix[r][c];
      if (value == target) return true;
      if (value > target) c--;
      else r++;
    }
    return false;
  }
}

class Solution {
  public void gameOfLife(int[][] board) {
    int m = board.length, n = board[0].length;
    for (int r = 0; r < m; r++) {
      for (int c = 0; c < n; c++) {
        int live = liveNeighbors(board, r, c);
        if (board[r][c] == 1 && (live < 2 || live > 3)) board[r][c] = -1;
        if (board[r][c] == 0 && live == 3) board[r][c] = 2;
      }
    }
    for (int r = 0; r < m; r++) {
      for (int c = 0; c < n; c++) board[r][c] = board[r][c] > 0 ? 1 : 0;
    }
  }

  private int liveNeighbors(int[][] board, int r, int c) {
    int count = 0;
    for (int dr = -1; dr <= 1; dr++) for (int dc = -1; dc <= 1; dc++) {
      if (dr == 0 && dc == 0) continue;
      int nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length && Math.abs(board[nr][nc]) == 1) count++;
    }
    return count;
  }
}

class Solution {
  public boolean exist(char[][] board, String word) {
    if (word.length() > board.length * board[0].length) return false;
    for (int r = 0; r < board.length; r++) {
      for (int c = 0; c < board[0].length; c++) {
        if (dfs(board, word, r, c, 0)) return true;
      }
    }
    return false;
  }

  private boolean dfs(char[][] board, String word, int r, int c, int index) {
    if (index == word.length()) return true;
    if (r < 0 || r == board.length || c < 0 || c == board[0].length || board[r][c] != word.charAt(index)) return false;
    char saved = board[r][c];
    board[r][c] = '#';
    boolean found = dfs(board, word, r + 1, c, index + 1) || dfs(board, word, r - 1, c, index + 1) || dfs(board, word, r, c + 1, index + 1) || dfs(board, word, r, c - 1, index + 1);
    board[r][c] = saved;
    return found;
  }
}

