class Solution {
  public List<List<Integer>> pacificAtlantic(int[][] heights) {
    int m = heights.length, n = heights[0].length;
    boolean[][] pacific = new boolean[m][n];
    boolean[][] atlantic = new boolean[m][n];
    Queue<int[]> pQueue = new ArrayDeque<>();
    Queue<int[]> aQueue = new ArrayDeque<>();

    for (int r = 0; r < m; r++) {
      add(pQueue, pacific, r, 0);
      add(aQueue, atlantic, r, n - 1);
    }
    for (int c = 0; c < n; c++) {
      add(pQueue, pacific, 0, c);
      add(aQueue, atlantic, m - 1, c);
    }
    bfs(heights, pQueue, pacific);
    bfs(heights, aQueue, atlantic);

    List<List<Integer>> answer = new ArrayList<>();
    for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
      if (pacific[r][c] && atlantic[r][c]) answer.add(Arrays.asList(r, c));
    }
    return answer;
  }

  private void add(Queue<int[]> queue, boolean[][] seen, int r, int c) {
    if (!seen[r][c]) {
      seen[r][c] = true;
      queue.offer(new int[]{r, c});
    }
  }

  private void bfs(int[][] h, Queue<int[]> queue, boolean[][] seen) {
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
    while (!queue.isEmpty()) {
      int[] cell = queue.poll();
      for (int d = 0; d < 4; d++) {
        int nr = cell[0] + dr[d], nc = cell[1] + dc[d];
        if (nr >= 0 && nr < h.length && nc >= 0 && nc < h[0].length && !seen[nr][nc] && h[nr][nc] >= h[cell[0]][cell[1]]) {
          seen[nr][nc] = true;
          queue.offer(new int[]{nr, nc});
        }
      }
    }
  }
}

