class Solution {
  public int shortestPathBinaryMatrix(int[][] grid) {
    int n = grid.length;
    if (grid[0][0] == 1 || grid[n - 1][n - 1] == 1) return -1;
    Queue<int[]> queue = new ArrayDeque<>();
    queue.offer(new int[]{0, 0});
    grid[0][0] = 1;
    int length = 1;
    int[] dir = {-1, 0, 1};

    while (!queue.isEmpty()) {
      for (int size = queue.size(); size > 0; size--) {
        int[] cell = queue.poll();
        if (cell[0] == n - 1 && cell[1] == n - 1) return length;
        for (int dr : dir) for (int dc : dir) {
          int nr = cell[0] + dr, nc = cell[1] + dc;
          if ((dr != 0 || dc != 0) && nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 0) {
            grid[nr][nc] = 1;
            queue.offer(new int[]{nr, nc});
          }
        }
      }
      length++;
    }
    return -1;
  }
}

class Solution {
  public boolean isToeplitzMatrix(int[][] matrix) {
    for (int r = 1; r < matrix.length; r++) {
      for (int c = 1; c < matrix[0].length; c++) {
        if (matrix[r][c] != matrix[r - 1][c - 1]) return false;
      }
    }
    return true;
  }
}

class Solution {
  public boolean isValidSudoku(char[][] board) {
    int[] rows = new int[9];
    int[] cols = new int[9];
    int[] boxes = new int[9];
    for (int r = 0; r < 9; r++) {
      for (int c = 0; c < 9; c++) {
        if (board[r][c] == '.') continue;
        int bit = 1 << (board[r][c] - '1');
        int box = (r / 3) * 3 + c / 3;
        if ((rows[r] & bit) != 0 || (cols[c] & bit) != 0 || (boxes[box] & bit) != 0) return false;
        rows[r] |= bit;
        cols[c] |= bit;
        boxes[box] |= bit;
      }
    }
    return true;
  }
}

class Solution {
  private int[] rows = new int[9];
  private int[] cols = new int[9];
  private int[] boxes = new int[9];

  public void solveSudoku(char[][] board) {
    for (int r = 0; r < 9; r++) for (int c = 0; c < 9; c++) {
      if (board[r][c] != '.') place(r, c, board[r][c] - '1');
    }
    solve(board, 0);
  }

  private boolean solve(char[][] board, int index) {
    if (index == 81) return true;
    int r = index / 9, c = index % 9;
    if (board[r][c] != '.') return solve(board, index + 1);
    int box = (r / 3) * 3 + c / 3;
    for (int digit = 0; digit < 9; digit++) {
      int bit = 1 << digit;
      if ((rows[r] & bit) != 0 || (cols[c] & bit) != 0 || (boxes[box] & bit) != 0) continue;
      board[r][c] = (char) ('1' + digit);
      place(r, c, digit);
      if (solve(board, index + 1)) return true;
      remove(r, c, digit);
      board[r][c] = '.';
    }
    return false;
  }

  private void place(int r, int c, int digit) {
    int bit = 1 << digit, box = (r / 3) * 3 + c / 3;
    rows[r] |= bit; cols[c] |= bit; boxes[box] |= bit;
  }

  private void remove(int r, int c, int digit) {
    int bit = ~(1 << digit), box = (r / 3) * 3 + c / 3;
    rows[r] &= bit; cols[c] &= bit; boxes[box] &= bit;
  }
}

class Solution {
  public int[] findDiagonalOrder(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[] answer = new int[m * n];
    int r = 0, c = 0;
    for (int i = 0; i < answer.length; i++) {
      answer[i] = mat[r][c];
      if ((r + c) % 2 == 0) {
        if (c == n - 1) r++;
        else if (r == 0) c++;
        else { r--; c++; }
      } else {
        if (r == m - 1) c++;
        else if (c == 0) r++;
        else { r++; c--; }
      }
    }
    return answer;
  }
}
